export const regionScenes4: Record<string, SceneModule> = bindContentSource("data:src/lib/scenes/regions4.ts#regionScenes4", {
  "tuyen-nuoc-bot": {
    slug: "tuyen-nuoc-bot",
    title: { vi: "Tuyến nước bọt và vùng mang tai", en: "Salivary Glands & Parotid Region", zh: "唾液腺与腮腺区" },
    description: {
      vi: "Ba đôi tuyến nước bọt lớn cùng vùng mang tai — nơi có một sắp xếp khiến mọi bệnh lý ở đây đều nguy hiểm hơn vẻ ngoài của nó. Tuyến mang tai bị bọc trong một bao xơ CHẮC và KHÔNG GIÃN được, nên viêm tuyến gây đau dữ dội hơn hẳn kích thước ổ viêm. Quan trọng hơn, THẦN KINH MẶT xuyên thẳng qua giữa tuyến rồi mới toả ra chi phối cơ bám da mặt: mọi khối u tuyến mang tai và mọi đường mổ ở đây đều phải tính đến dây này trước tiên, vì cắt đứt nó là liệt nửa mặt vĩnh viễn. Ba tuyến tiết ra chừng một lít rưỡi nước bọt mỗi ngày, và tính chất dịch của mỗi tuyến khác nhau nên sỏi ống tuyến gần như chỉ gặp ở tuyến dưới hàm.",
      en: "The three paired major salivary glands and the parotid region, where the anatomy makes every disorder more serious than it looks. The parotid is wrapped in a tough, unyielding capsule, so inflammation hurts far more than its size suggests. More importantly the FACIAL NERVE passes straight through the gland before fanning out to the muscles of facial expression: every parotid tumour and every incision here must account for it, since dividing it means permanent facial palsy.",
      zh: "三对大唾液腺及腮腺区。腮腺包被于坚韧而无弹性的筋膜鞘内，故炎症疼痛远超其体积所示。更重要的是面神经径直穿过腺体后才分支支配表情肌：此处的每一个肿瘤与每一次切口都须首先顾及此神经，切断即致永久性面瘫。",
    },
    visibleSystems: ["visceral"],
    modelFile: "/models/salivary_glands.glb",
    hotspots: [
      { key: "parotid-gland", meshName: "Parotid gland.r", offset: [0, 0], label: { vi: "Tuyến mang tai", en: "Parotid gland", zh: "腮腺" }, latinName: "Glandula parotidea",
        note: { vi: "Tuyến nước bọt LỚN NHẤT, nằm trong hố sau hàm giữa ngành hàm dưới và mỏm chũm, tiết dịch loãng thuần thanh dịch. Bao tuyến dày và không giãn nên viêm tuyến mang tai (quai bị) gây đau bật lên khi nhai. Vì tuyến ôm sát ngành hàm, tuyến sưng đẩy dái tai ra NGOÀI và LÊN TRÊN — dấu hiệu phân biệt với hạch cổ sưng, vốn không làm dái tai vểnh.", en: "The LARGEST salivary gland, in the retromandibular fossa between the mandibular ramus and mastoid, secreting watery serous saliva. Its tight capsule makes parotitis (mumps) exquisitely painful on chewing. Because it wraps the ramus, swelling lifts the earlobe OUTWARDS and UPWARDS — the sign distinguishing it from cervical lymphadenopathy.", zh: "最大的唾液腺，位于下颌支与乳突之间的下颌后窝，分泌稀薄浆液性唾液。被膜致密无弹性，故腮腺炎（流行性腮腺炎）咀嚼时剧痛。因包绕下颌支，肿大时将耳垂向外上方推起——此征可与颈淋巴结肿大鉴别。" } },
      { key: "facial-nerve-parotid", meshName: "Facial nerve (VII).r.001", offset: [0, 0], label: { vi: "Thần kinh mặt (VII) trong tuyến mang tai", en: "Facial nerve within the parotid", zh: "面神经（腮腺内）" }, latinName: "Nervus facialis",
        note: { vi: "Rời sọ qua lỗ trâm chũm rồi CHUI THẲNG vào tuyến mang tai, chia thành hai thân rồi năm nhánh tận toả ra như chân ngỗng. Chính dây này chia tuyến thành thuỳ nông và thuỳ sâu — một ranh giới không có thật về mô học mà hoàn toàn do đường đi của dây thần kinh tạo ra, nhưng lại quyết định mọi kỹ thuật mổ tuyến. Mốc tìm dây khi mổ là điểm giữa mỏm trâm và mỏm chũm.", en: "Leaves the skull through the stylomastoid foramen and passes DIRECTLY into the parotid, dividing into two trunks then five terminal branches. The nerve alone defines the gland's 'superficial' and 'deep' lobes — a plane with no histological basis but which governs all parotid surgery. It is located between the styloid and mastoid processes.", zh: "经茎乳孔出颅后径直入腮腺，分为两干继而五支呈鹅足状散开。腮腺的浅、深叶完全由该神经的走行划分——组织学上并不存在此界面，却决定了全部腮腺手术方式。手术中以茎突与乳突之间定位该神经。" } },
      { key: "parotid-duct", meshName: "Parotid duct.r.001", offset: [0, 0], label: { vi: "Ống tuyến mang tai (ống Stensen)", en: "Parotid duct", zh: "腮腺管" }, latinName: "Ductus parotideus",
        note: { vi: "Chạy ngang trên mặt ngoài cơ cắn rồi BẺ VUÔNG GÓC xuyên qua cơ mút để đổ vào tiền đình miệng ngang răng hàm lớn thứ hai trên. Góc gấp đó là chỗ hẹp nhất, nhưng vì dịch tuyến mang tai loãng và ít canxi nên sỏi ở đây hiếm. Đường đi nông ngay dưới da má khiến ống dễ bị đứt trong vết thương vùng má — dò nước bọt ra da là biến chứng khó chịu.", en: "Runs across the masseter then turns SHARPLY through buccinator to open opposite the upper second molar. That right-angle bend is its narrowest point, but the thin, calcium-poor parotid secretion makes stones here uncommon. Its superficial course means cheek lacerations readily divide it, producing a troublesome salivary fistula.", zh: "横过咬肌表面后呈直角穿颊肌，开口于上颌第二磨牙相对处。该直角为最窄处，但腮腺分泌稀薄、含钙少，故此处结石少见。行程表浅，颊部裂伤易将其切断，形成难处理的涎瘘。" } },
      { key: "submandibular-gland", meshName: "Submandibular gland.r", offset: [0, 0], label: { vi: "Tuyến dưới hàm", en: "Submandibular gland", zh: "下颌下腺" }, latinName: "Glandula submandibularis",
        note: { vi: "Tuyến hỗn hợp thanh dịch – nhầy, cuộn hình móc câu quanh bờ sau cơ hàm móng nên có phần nông và phần sâu nối nhau. Đây là tuyến tiết phần lớn nước bọt lúc nghỉ, và dịch của nó ĐẶC, GIÀU CANXI. Cộng thêm ống tuyến phải chạy NGƯỢC LÊN DỐC mới tới sàn miệng, đây là lý do khoảng 80% sỏi tuyến nước bọt nằm ở tuyến dưới hàm.", en: "A mixed sero-mucous gland hooked around the posterior border of mylohyoid, so it has superficial and deep parts. It produces most resting saliva, and its secretion is THICK and CALCIUM-RICH. Combined with a duct that must run UPHILL to the floor of the mouth, this is why about 80% of salivary calculi occur here.", zh: "浆液–黏液混合腺，钩绕下颌舌骨肌后缘，故分浅、深两部。静息状态下唾液主要由其分泌，分泌物黏稠且富含钙。加之其导管须逆行向上至口底，故约80%的涎石发生于此。" } },
      { key: "submandibular-duct", meshName: "Submandibular duct.r.001", offset: [0, 0], label: { vi: "Ống tuyến dưới hàm (ống Wharton)", en: "Submandibular duct", zh: "下颌下腺管" }, latinName: "Ductus submandibularis",
        note: { vi: "Đi từ phần sâu của tuyến ra trước, luồn giữa cơ cằm lưỡi và cơ hàm móng để đổ ở cục dưới lưỡi cạnh hãm lưỡi. Trên đường đi nó bị THẦN KINH LƯỠI vắt qua hai lần theo kiểu bắt chéo — dây thần kinh chui từ ngoài vào trong dưới ống rồi vòng lên trên. Vì thế mổ lấy sỏi ống tuyến luôn có nguy cơ tê nửa lưỡi cùng bên.", en: "Runs forward from the deep part of the gland between genioglossus and mylohyoid to open at the sublingual caruncle. On the way the LINGUAL NERVE crosses it twice, passing below then hooking above — which is why surgery for duct stones always risks numbing that half of the tongue.", zh: "自腺深部前行，经颏舌肌与下颌舌骨肌之间，开口于舌下阜。途中舌神经两次跨越该管，先自其下方绕至上方——故导管取石手术始终有同侧舌麻木的风险。" } },
      { key: "sublingual-gland", meshName: "Sublingual gland.r", offset: [0, 0], label: { vi: "Tuyến dưới lưỡi", en: "Sublingual gland", zh: "舌下腺" }, latinName: "Glandula sublingualis",
        note: { vi: "Tuyến nhỏ nhất trong ba tuyến lớn, nằm ngay dưới niêm mạc sàn miệng, tiết dịch chủ yếu là NHẦY. Khác hai tuyến kia, nó không có một ống chính lớn mà đổ ra bằng hàng chục ống nhỏ trực tiếp lên nếp dưới lưỡi. Chấn thương làm rách các ống nhỏ đó khiến nước bọt tụ lại thành nang nhái — khối phồng xanh trong ở sàn miệng.", en: "The smallest of the three, lying just under the floor-of-mouth mucosa and secreting mainly MUCUS. Unlike the others it has no single large duct but dozens of small ducts opening onto the sublingual fold. Trauma tearing these produces a ranula — a translucent bluish swelling in the floor of the mouth.", zh: "三大腺中最小者，位于口底黏膜下，主要分泌黏液。与另两腺不同，其无单一主导管，而以数十条小管开口于舌下襞。外伤撕裂这些小管即形成舌下囊肿——口底半透明蓝色隆起。" } },
      { key: "retromandibular-vein", meshName: "Retromandibular vein.r.001", offset: [0, 0], label: { vi: "Tĩnh mạch sau hàm", en: "Retromandibular vein", zh: "下颌后静脉" }, latinName: "Vena retromandibularis",
        note: { vi: "Do tĩnh mạch thái dương nông hợp với tĩnh mạch hàm trên tạo thành TRONG lòng tuyến mang tai. Nó là mốc định vị quan trọng khi mổ: trong tuyến, thứ tự từ NÔNG vào SÂU là thần kinh mặt — tĩnh mạch sau hàm — động mạch cảnh ngoài. Nhớ đúng ba tầng đó là biết mình đang ở độ sâu nào khi bóc tách.", en: "Formed WITHIN the parotid by the superficial temporal and maxillary veins. It is a key surgical landmark: from SUPERFICIAL to DEEP the gland contains the facial nerve, then this vein, then the external carotid artery — three layers that tell the surgeon how deep the dissection has reached.", zh: "由颞浅静脉与上颌静脉在腮腺实质内汇合而成。是重要手术标志：腺内由浅入深依次为面神经、下颌后静脉、颈外动脉——记住此三层即知分离深度。" } },
      { key: "external-carotid-parotid", meshName: "External carotid artery.r.001", offset: [0, 0], label: { vi: "Động mạch cảnh ngoài (đoạn trong tuyến)", en: "External carotid artery in the gland", zh: "颈外动脉（腺内段）" }, latinName: "Arteria carotis externa",
        note: { vi: "Cấu trúc nằm SÂU NHẤT trong ba tầng của tuyến mang tai. Nó chui vào tuyến từ dưới rồi chia đôi thành động mạch thái dương nông và động mạch hàm trên ngay trong lòng tuyến. Vì mạch nằm sâu, khối u thuỳ sâu tuyến mang tai đẩy vào thành bên hầu và có thể sờ thấy qua đường miệng chứ không thấy rõ từ ngoài.", en: "The DEEPEST of the three structures in the parotid. It enters from below and divides into the superficial temporal and maxillary arteries inside the gland. Because it lies deep, deep-lobe tumours bulge into the lateral pharyngeal wall and are felt intra-orally rather than seen externally.", zh: "腮腺三层结构中最深者。自下方入腺，并在腺实质内分为颞浅动脉与上颌动脉。因位置深在，深叶肿瘤向咽侧壁膨隆，经口内可扪及而外观不明显。" } },
      { key: "masseter-parotid", meshName: "Deep part of masseter.r", offset: [0, 0], label: { vi: "Cơ cắn", en: "Masseter", zh: "咬肌" }, latinName: "Musculus masseter",
        note: { vi: "Cơ nhai khoẻ nhất, phủ mặt ngoài ngành hàm và làm NỀN cho tuyến mang tai trượt lên. Cắn răng lại thì cơ nổi cứng, đẩy tuyến ra trước — đây là thủ thuật khám đơn giản để phân biệt khối u tuyến với khối u cơ cắn. Phì đại cơ cắn hai bên do nghiến răng làm khuôn mặt bạnh vuông, hay bị nhầm là bệnh tuyến mang tai.", en: "The strongest muscle of mastication, covering the mandibular ramus and forming the BED on which the parotid rests. Clenching makes it hard and pushes the gland forward — a simple bedside test separating a glandular from a masseteric mass. Bilateral hypertrophy from bruxism squares the jawline and is often mistaken for parotid disease.", zh: "最强的咀嚼肌，覆盖下颌支外面，构成腮腺所附着的床。咬紧牙关时其变硬并将腺体向前推——此简易检查可鉴别腺源性与咬肌源性肿块。磨牙所致双侧肥大使下颌角方正，常被误认为腮腺疾病。" } },
    ],
  },

  "xoang-tinh-mach-mang-cung": {
    slug: "xoang-tinh-mach-mang-cung",
    title: { vi: "Xoang tĩnh mạch màng cứng", en: "Dural Venous Sinuses", zh: "硬脑膜静脉窦" },
    description: {
      vi: "Hệ thống dẫn máu tĩnh mạch của não — và là một hệ khác hẳn mọi tĩnh mạch còn lại của cơ thể. Các xoang này không phải mạch máu có thành cơ, mà là những KHE nằm giữa hai lá màng cứng, thành cứng nên KHÔNG XẸP được và KHÔNG CÓ VAN. Chính hai đặc điểm đó quyết định toàn bộ bệnh lý ở đây: xoang không xẹp nên rách xoang khi vỡ sọ thì máu chảy không cầm được và khí có thể bị hút vào gây tắc mạch khí; không có van nên nhiễm trùng ở mặt có thể chảy NGƯỢC dòng vào trong sọ. Máu não gom dần từ xoang dọc trên qua hội lưu rồi theo xoang ngang, xoang sigma mà đổ vào tĩnh mạch cảnh trong.",
      en: "The venous drainage of the brain, unlike any other vein in the body. These are not muscular vessels but CLEFTS between two layers of dura: rigid-walled, so they cannot collapse, and VALVELESS. Those two facts explain the pathology here — a torn sinus in a skull fracture bleeds uncontrollably and can entrain air, while the absence of valves lets facial infection flow BACKWARDS into the cranium. Blood collects along the superior sagittal sinus to the confluence, then via transverse and sigmoid sinuses into the internal jugular vein.",
      zh: "脑的静脉引流系统，与全身其他静脉迥异。它们并非有肌层的血管，而是两层硬脑膜之间的裂隙：管壁坚硬不能塌陷，且无瓣膜。此二特性决定了本区病理——颅骨骨折撕裂窦壁则出血难止并可吸入空气，而无瓣膜使面部感染可逆流入颅。血液沿上矢状窦汇至窦汇，再经横窦、乙状窦注入颈内静脉。",
    },
    visibleSystems: ["cardiovascular"],
    modelFile: "/models/dural_sinuses.glb",
    hotspots: [
      { key: "superior-sagittal-sinus", meshName: "Superior sagittal sinus.001", offset: [0, 0], label: { vi: "Xoang dọc trên", en: "Superior sagittal sinus", zh: "上矢状窦" }, latinName: "Sinus sagittalis superior",
        note: { vi: "Chạy dọc bờ trên liềm đại não từ trước ra sau, to dần về phía sau. Đây là nơi các HẠT MÀNG NHỆN nhô vào để trả dịch não tuỷ về máu, nên tắc xoang này vừa gây tăng áp lực nội sọ do ứ máu vừa do ứ dịch não tuỷ. Vì nằm đúng đường giữa ngay dưới xương sọ, đường mổ vượt đường giữa vùng đỉnh luôn phải né xoang.", en: "Runs along the upper border of the falx from front to back, widening posteriorly. The ARACHNOID GRANULATIONS project into it to return CSF to the blood, so thrombosis here raises intracranial pressure both by venous congestion and by blocking CSF absorption. Lying in the midline just under the vault, midline parietal approaches must avoid it.", zh: "沿大脑镰上缘由前向后走行，向后渐增粗。蛛网膜颗粒突入其内将脑脊液回吸收入血，故此窦血栓既因静脉淤血又因脑脊液吸收受阻而升高颅内压。因位于中线颅骨正下方，顶部跨中线入路须避开。" } },
      { key: "inferior-sagittal-sinus", meshName: "Inferior sagittal sinus.001", offset: [0, 0], label: { vi: "Xoang dọc dưới", en: "Inferior sagittal sinus", zh: "下矢状窦" }, latinName: "Sinus sagittalis inferior",
        note: { vi: "Nhỏ hơn nhiều, chạy dọc bờ TỰ DO phía dưới của liềm đại não. Nó nhận máu từ mặt trong bán cầu rồi hợp với tĩnh mạch não lớn để thành xoang thẳng. Vị trí ở bờ tự do khiến nó nằm ngay sát chỗ hồi đai chui xuống khi có thoát vị dưới liềm — một lý do nữa khiến khối choán chỗ một bên gây tổn thương lan sang bên đối diện.", en: "Much smaller, running in the FREE lower border of the falx. It drains the medial hemisphere and joins the great cerebral vein to form the straight sinus. Its position at the free edge places it right where the cingulate gyrus herniates in subfalcine shift.", zh: "较细，行于大脑镰游离下缘。引流半球内侧面，与大脑大静脉汇合成直窦。因位于游离缘，恰处于扣带回发生镰下疝之处。" } },
      { key: "straight-sinus", meshName: "Straight sinus.001", offset: [0, 0], label: { vi: "Xoang thẳng", en: "Straight sinus", zh: "直窦" }, latinName: "Sinus rectus",
        note: { vi: "Nằm ở chỗ liềm đại não gặp lều tiểu não, nhận máu SÂU của não qua tĩnh mạch não lớn — nghĩa là máu từ đồi thị, nhân nền và đám rối màng mạch. Tắc xoang thẳng vì thế cho bệnh cảnh rất nặng và rất riêng: phù hai bên đồi thị đối xứng trên phim, người bệnh lơ mơ nhanh chóng chứ không có dấu thần kinh khu trú rõ.", en: "Lies where the falx meets the tentorium and receives the DEEP venous drainage through the great cerebral vein — thalamus, basal ganglia and choroid plexus. Its thrombosis therefore gives a distinctive severe picture: symmetrical bilateral thalamic oedema with rapid depression of consciousness rather than focal signs.", zh: "位于大脑镰与小脑幕交界处，经大脑大静脉接受脑深部静脉血——丘脑、基底核与脉络丛。故直窦血栓表现独特而严重：影像上双侧丘脑对称性水肿，意识迅速障碍而无明显局灶体征。" } },
      { key: "transverse-sinus", meshName: "Transverse sinus.r.001", offset: [0, 0], label: { vi: "Xoang ngang", en: "Transverse sinus", zh: "横窦" }, latinName: "Sinus transversus",
        note: { vi: "Chạy ngang trong bờ bám của lều tiểu não, dẫn máu từ hội lưu ra hai bên. Hai xoang ngang thường KHÔNG ĐỀU NHAU — bên phải to hơn ở đa số người vì nó nối tiếp xoang dọc trên, còn bên trái nối tiếp xoang thẳng. Biết điều này để không đọc nhầm bên nhỏ hơn là huyết khối trên phim mạch.", en: "Runs laterally in the attached margin of the tentorium, carrying blood from the confluence. The two are usually ASYMMETRIC — the right is larger in most people because it continues the superior sagittal sinus while the left continues the straight sinus. Knowing this prevents mistaking the smaller side for thrombosis on venography.", zh: "沿小脑幕附着缘向外走行，将窦汇的血液导向两侧。两侧常不对称——多数人右侧较粗，因其续于上矢状窦，而左侧续于直窦。知此可避免将较细一侧误判为静脉造影上的血栓。" } },
      { key: "sigmoid-sinus", meshName: "Sigmoid sinus.r.001", offset: [0, 0], label: { vi: "Xoang sigma", en: "Sigmoid sinus", zh: "乙状窦" }, latinName: "Sinus sigmoideus",
        note: { vi: "Đoạn cong hình chữ S nối xoang ngang với lỗ tĩnh mạch cảnh, chạy trong một rãnh sâu ở mặt trong xương chũm — chỉ cách các thông bào chũm một vách xương mỏng. Chính sự sát vách đó khiến viêm tai giữa và viêm xương chũm có thể lan thẳng vào xoang gây huyết khối xoang sigma, biến chứng nội sọ kinh điển của viêm tai.", en: "The S-shaped segment joining the transverse sinus to the jugular foramen, running in a deep groove on the inner surface of the mastoid — separated from the mastoid air cells by only a thin plate. That proximity is why otitis media and mastoiditis can spread directly into it, causing sigmoid sinus thrombosis, the classic intracranial complication of ear infection.", zh: "连接横窦与颈静脉孔的S形段，行于乳突内面的深沟内，与乳突气房仅隔薄骨板。正因如此，中耳炎与乳突炎可直接蔓延引起乙状窦血栓，是耳部感染的经典颅内并发症。" } },
      { key: "cavernous-sinus", meshName: "Cavernous sinus.r", offset: [0, 0], label: { vi: "Xoang hang", en: "Cavernous sinus", zh: "海绵窦" }, latinName: "Sinus cavernosus",
        note: { vi: "Xoang quan trọng nhất về lâm sàng, nằm hai bên thân xương bướm cạnh hố yên. Điều làm nó đặc biệt là các cấu trúc ĐI XUYÊN QUA nó: động mạch cảnh trong chạy ngay trong lòng xoang, còn các dây III, IV, V1, V2 và VI đi trong thành ngoài — riêng dây VI nằm TỰ DO trong lòng xoang cạnh động mạch nên bị tổn thương SỚM NHẤT. Vì thế liệt riêng dây VI là dấu hiệu đầu tiên của huyết khối xoang hang.", en: "The most clinically important sinus, flanking the sphenoid body beside the pituitary fossa. What makes it special is what runs THROUGH it: the internal carotid artery lies within its lumen, while nerves III, IV, V1, V2 run in its lateral wall — but nerve VI lies FREE in the lumen beside the artery and is therefore injured FIRST. An isolated sixth nerve palsy is thus the earliest sign of cavernous sinus thrombosis.", zh: "临床上最重要的窦，位于蝶骨体两侧、垂体窝旁。其特殊之处在于穿行其中的结构：颈内动脉行于窦腔内，而III、IV、V1、V2神经行于外侧壁——唯独VI神经游离于窦腔内、紧邻动脉，故最先受累。孤立性外展神经麻痹即海绵窦血栓最早的体征。" } },
      { key: "intercavernous-sinus", meshName: "Anterior intercavernous sinus.001", offset: [0, 0], label: { vi: "Xoang gian hang trước", en: "Anterior intercavernous sinus", zh: "前海绵间窦" }, latinName: "Sinus intercavernosus anterior",
        note: { vi: "Nối hai xoang hang ở trước và sau hố yên, làm chúng thành một vòng khép kín quanh tuyến yên — nên còn gọi là xoang vòng. Hệ quả lâm sàng: nhiễm trùng hoặc huyết khối một bên rất dễ LAN SANG BÊN KIA qua đường nối này, biến bệnh một bên thành hai bên trong vòng vài ngày. Đây cũng là chỗ dễ chảy máu khi mổ tuyến yên qua xoang bướm.", en: "Links the two cavernous sinuses in front of and behind the pituitary fossa, making a closed ring around the gland. Clinically this lets infection or thrombosis on one side SPREAD to the other within days, turning a unilateral disease bilateral; it is also a source of bleeding in trans-sphenoidal pituitary surgery.", zh: "于垂体窝前后连接两侧海绵窦，围绕垂体形成闭合环。临床上使一侧的感染或血栓在数日内蔓延至对侧，由单侧转为双侧；亦是经蝶垂体手术的出血来源。" } },
      { key: "superior-petrosal-sinus", meshName: "Superior petrosal sinus.r.001", offset: [0, 0], label: { vi: "Xoang đá trên", en: "Superior petrosal sinus", zh: "岩上窦" }, latinName: "Sinus petrosus superior",
        note: { vi: "Chạy dọc bờ trên phần đá xương thái dương trong chỗ bám của lều tiểu não, dẫn máu từ xoang hang ra xoang ngang. Nó là đường THOÁT phụ của xoang hang: khi xoang hang bị tắc, máu tìm đường qua đây và qua xoang đá dưới. Trong mổ u góc cầu tiểu não, xoang này thường phải cắt để mở đường vào.", en: "Runs along the upper border of the petrous temporal bone in the tentorial attachment, draining the cavernous sinus into the transverse sinus. It is a collateral OUTLET for the cavernous sinus when that is obstructed, and is commonly divided to gain access in cerebellopontine angle surgery.", zh: "沿颞骨岩部上缘、于小脑幕附着处走行，将海绵窦血液导入横窦。是海绵窦阻塞时的侧支流出道；桥小脑角手术中常需切断以获得入路。" } },
      { key: "occipital-sinus", meshName: "Occipital sinus.001", offset: [0, 0], label: { vi: "Xoang chẩm", en: "Occipital sinus", zh: "枕窦" }, latinName: "Sinus occipitalis",
        note: { vi: "Xoang nhỏ nhất, nằm trong bờ bám của liềm tiểu não, chạy từ hội lưu xuống quanh lỗ lớn xương chẩm rồi nối với đám rối tĩnh mạch quanh ống sống. Chính chỗ nối đó biến hệ xoang màng cứng thành một phần của hệ tĩnh mạch cột sống KHÔNG VAN — con đường giải thích vì sao ung thư tuyến tiền liệt hay di căn lên cột sống và nền sọ mà không qua phổi.", en: "The smallest sinus, in the attached border of the falx cerebelli, running from the confluence around the foramen magnum to join the vertebral venous plexus. That junction makes the dural sinuses part of the VALVELESS vertebral venous system — the route explaining why prostate cancer metastasises to spine and skull base without passing through the lungs.", zh: "最小的窦，位于小脑镰附着缘，自窦汇绕枕骨大孔下行，与椎静脉丛相连。此连接使硬脑膜窦成为无瓣膜椎静脉系统的一部分——正是前列腺癌不经肺而转移至脊柱与颅底的通路。" } },
    ],
  },

  "ho-khoeo": {
    slug: "ho-khoeo",
    title: { vi: "Hố khoeo", en: "The Popliteal Fossa", zh: "腘窝" },
    description: {
      vi: "Vùng trám ở mặt sau gối — cửa ngõ duy nhất cho mạch và thần kinh đi từ đùi xuống cẳng chân. Bốn cạnh của hố do gân các cơ ụ ngồi cẳng chân và hai đầu cơ bụng chân tạo nên; sàn hố là mặt sau khớp gối. Điều cần nhớ nhất là THỨ TỰ TỪ SÂU RA NÔNG của ba cấu trúc chính: động mạch khoeo nằm sát xương nhất, rồi tới tĩnh mạch, ngoài cùng là thần kinh chày. Thứ tự đó giải thích vì sao trật khớp gối ra sau làm rách động mạch khoeo trước khi chạm tới thần kinh, và vì sao mạch nằm sâu nên khó bắt được mạch khoeo trên người bình thường nếu không gấp gối cho cơ chùng.",
      en: "The diamond-shaped region behind the knee — the only gateway for vessels and nerves passing from thigh to leg. Its borders are the hamstring tendons above and the two heads of gastrocnemius below; its floor is the back of the knee joint. The key point is the order from DEEP to SUPERFICIAL: popliteal artery closest to bone, then vein, then tibial nerve most superficial. That order explains why posterior knee dislocation tears the artery before reaching the nerve, and why the popliteal pulse is hard to feel unless the knee is flexed to relax the fascia.",
      zh: "膝后菱形区——大腿至小腿血管神经的唯一通道。上界为腘绳肌腱，下界为腓肠肌两头，底为膝关节后面。最须记住的是由深至浅的顺序：腘动脉最贴骨面，其次为静脉，胫神经最浅。此顺序解释了膝关节后脱位为何先撕裂动脉，以及为何不屈膝放松筋膜便难以触及腘动脉搏动。",
    },
    visibleSystems: ["muscular"],
    modelFile: "/models/popliteal_fossa.glb",
    hotspots: [
      { key: "popliteal-artery", meshName: "Popliteal artery.r.001", offset: [0, 0], label: { vi: "Động mạch khoeo", en: "Popliteal artery", zh: "腘动脉" }, latinName: "Arteria poplitea",
        note: { vi: "Đoạn tiếp của động mạch đùi sau khi chui qua vòng gân cơ khép, nằm SÂU NHẤT trong hố, áp thẳng vào mặt sau bao khớp gối. Vì bị kẹp giữa xương và mô chắc ở cả hai đầu, nó gần như không di động — nên trật khớp gối ra sau hoặc gãy trên lồi cầu đùi làm rách động mạch trong tới một phần ba số ca. Chi dưới lại nghèo vòng nối nên tắc mạch khoeo là cấp cứu cắt cụt.", en: "The continuation of the femoral artery beyond the adductor hiatus, lying DEEPEST in the fossa against the back of the knee capsule. Tethered at both ends, it barely moves — so posterior knee dislocation or supracondylar fracture tears it in up to a third of cases. With poor collateral supply in the leg, popliteal occlusion is a limb-threatening emergency.", zh: "股动脉穿收肌腱裂孔后的延续，位于腘窝最深层，紧贴膝关节囊后面。两端被固定而几乎不能移动，故膝关节后脱位或股骨髁上骨折中，约三分之一伴动脉撕裂。小腿侧支循环差，腘动脉阻塞属危及肢体的急症。" } },
      { key: "popliteal-vein", meshName: "Popliteal vein.r.001", offset: [0, 0], label: { vi: "Tĩnh mạch khoeo", en: "Popliteal vein", zh: "腘静脉" }, latinName: "Vena poplitea",
        note: { vi: "Nằm giữa động mạch (sâu) và thần kinh chày (nông), dính chặt vào động mạch trong một bao chung. Chính vì hai mạch chung bao nên vết thương ở đây dễ tạo THÔNG ĐỘNG – TĨNH MẠCH. Đây cũng là mốc dưới của huyết khối tĩnh mạch sâu: cục máu từ tĩnh mạch bắp chân lan lên tới đoạn khoeo là chuyển thành nguy cơ thuyên tắc phổi thực sự.", en: "Lies between the artery (deep) and tibial nerve (superficial), bound to the artery in a common sheath — which is why penetrating wounds here readily create an ARTERIOVENOUS FISTULA. It also marks the threshold in deep vein thrombosis: clot extending from calf veins into the popliteal segment becomes a genuine pulmonary embolism risk.", zh: "位于动脉（深）与胫神经（浅）之间，与动脉共处一鞘，故此处穿透伤易形成动静脉瘘。它也是深静脉血栓的分界：血栓自小腿静脉蔓延至腘段即构成真正的肺栓塞风险。" } },
      { key: "tibial-nerve-popliteal", meshName: "Tibial nerve.r.001", offset: [0, 0], label: { vi: "Thần kinh chày", en: "Tibial nerve", zh: "胫神经" }, latinName: "Nervus tibialis",
        note: { vi: "Nhánh tận LỚN HƠN của thần kinh toạ, đi thẳng xuống chính giữa hố khoeo và nằm NÔNG NHẤT trong bộ ba. Vì nông nhất nên nó là cấu trúc đầu tiên gặp khi bóc tách từ sau, và cũng là dây dễ phong bế nhất ở đây. Trên đường qua hố nó cho nhánh bì bắp chân trong và các nhánh cơ tới hai đầu cơ bụng chân, cơ dép và cơ khoeo.", en: "The LARGER terminal branch of the sciatic nerve, descending through the middle of the fossa as the MOST SUPERFICIAL of the three. Being superficial it is the first structure met on posterior dissection and the easiest to block here. In the fossa it gives the medial sural cutaneous nerve and motor branches to gastrocnemius, soleus and popliteus.", zh: "坐骨神经较粗的终支，自腘窝正中下行，为三者中最浅者。因位置最浅，后方分离时最先遇及，也最便于在此阻滞。在窝内发出腓肠内侧皮神经及支配腓肠肌、比目鱼肌与腘肌的肌支。" } },
      { key: "common-fibular-popliteal", meshName: "Common fibular nerve.r.001", offset: [0, 0], label: { vi: "Thần kinh mác chung", en: "Common fibular nerve", zh: "腓总神经" }, latinName: "Nervus fibularis communis",
        note: { vi: "Tách khỏi thần kinh toạ ở đỉnh hố rồi đi CHẾCH RA NGOÀI men theo bờ trong gân cơ nhị đầu đùi — nghĩa là nó rời hố khoeo ở góc ngoài chứ không đi xuống giữa như dây chày. Đường đi ra ngoài ấy dẫn nó tới cổ xương mác, nơi nó nằm nông nhất cơ thể và dễ bị ép nhất. Nhớ được hướng đi chếch này là biết vì sao chấn thương gối kiểu vẹo trong hay kèm bàn chân rủ.", en: "Leaves the sciatic nerve at the apex and runs OBLIQUELY LATERAL along the medial border of the biceps femoris tendon — exiting at the lateral angle rather than descending centrally. That oblique course carries it to the fibular neck where it is the most superficial large nerve in the body. This is why varus knee injuries so often come with foot drop.", zh: "于窝尖处自坐骨神经分出，沿股二头肌腱内侧缘斜向外下——自外侧角出窝而非居中下行。此斜行走向将其带至腓骨颈，成为全身位置最浅的大神经。故膝内翻损伤常伴足下垂。" } },
      { key: "biceps-femoris", meshName: "Long head of biceps femoris.r", offset: [0, 0], label: { vi: "Cơ nhị đầu đùi (bờ trên ngoài)", en: "Biceps femoris — superolateral border", zh: "股二头肌（上外侧界）" }, latinName: "Musculus biceps femoris",
        note: { vi: "Gân của nó tạo BỜ TRÊN NGOÀI của hố khoeo và là mốc sờ được dễ nhất ở mặt sau gối. Lần theo gân này xuống dưới là tới chỏm xương mác, và thần kinh mác chung nằm ngay sát bờ trong gân — đây chính là cách tìm dây mác trên lâm sàng mà không cần siêu âm. Đầu dài do thần kinh chày chi phối, đầu ngắn do thần kinh mác, một điểm hay bị hỏi.", en: "Its tendon forms the SUPEROLATERAL border of the fossa and is the easiest landmark to palpate behind the knee. Following it down leads to the fibular head, with the common fibular nerve lying against its medial border — the clinical way to find the nerve without ultrasound. The long head is tibial-innervated, the short head fibular-innervated.", zh: "其肌腱构成腘窝上外侧界，是膝后最易触及的标志。沿其下行即达腓骨头，腓总神经紧贴其内侧缘——这是临床上无需超声即可定位该神经的方法。长头由胫神经支配，短头由腓总神经支配。" } },
      { key: "semimembranosus", meshName: "Semimembranosus muscle.r", offset: [0, 0], label: { vi: "Cơ bán màng (bờ trên trong)", en: "Semimembranosus — superomedial border", zh: "半膜肌（上内侧界）" }, latinName: "Musculus semimembranosus",
        note: { vi: "Cùng cơ bán gân tạo BỜ TRÊN TRONG của hố. Gân bám tận của nó toả ra thành dây chằng khoeo chéo góp phần giữ vững mặt sau khớp gối. Túi hoạt dịch giữa cơ này và đầu trong cơ bụng chân khi căng phồng cho ra NANG BAKER — khối phồng ở góc trong trên hố khoeo, vỡ ra thì đau bắp chân đột ngột rất giống huyết khối tĩnh mạch sâu.", en: "With semitendinosus it forms the SUPEROMEDIAL border. Its insertion expands into the oblique popliteal ligament stabilising the back of the knee. The bursa between it and the medial head of gastrocnemius, when distended, is a BAKER CYST — a swelling at the superomedial angle whose rupture causes sudden calf pain closely mimicking deep vein thrombosis.", zh: "与半腱肌共同构成上内侧界。其止点扩展为腘斜韧带，稳定膝关节后面。它与腓肠肌内侧头之间的滑囊膨大即Baker囊肿——位于上内侧角的肿物，破裂时突发小腿痛，酷似深静脉血栓。" } },
      { key: "gastrocnemius-medial", meshName: "Medial head of gastrocnemius.r", offset: [0, 0], label: { vi: "Đầu trong cơ bụng chân (bờ dưới trong)", en: "Gastrocnemius, medial head", zh: "腓肠肌内侧头" }, latinName: "Caput mediale musculi gastrocnemii",
        note: { vi: "Tạo BỜ DƯỚI TRONG của hố, xuất phát từ ngay trên lồi cầu trong xương đùi. Đây là cơ duy nhất bắc qua cả khớp gối lẫn khớp cổ chân, nên độ căng của nó phụ thuộc tư thế gối — lý do phải gấp gối khi khám tầm gấp mu chân. Rách chỗ nối gân cơ đầu trong khi bật nhảy đột ngột gọi là “chân quần vợt”, đau nhói bắp chân trong.", en: "Forms the INFEROMEDIAL border, arising just above the medial femoral condyle. It is the only muscle crossing both the knee and the ankle, so its tension depends on knee position — hence the knee must be flexed when testing ankle dorsiflexion. A tear at its musculotendinous junction on sudden push-off is 'tennis leg'.", zh: "构成下内侧界，起自股骨内侧髁上方。是唯一跨越膝与踝两个关节的肌肉，其张力随膝位而变——故检查踝背伸活动度时须屈膝。突然蹬地致其肌腱结合部撕裂即“网球腿”。" } },
      { key: "oblique-popliteal", meshName: "Oblique popliteal ligament.r", offset: [0, 0], label: { vi: "Dây chằng khoeo chéo", en: "Oblique popliteal ligament", zh: "腘斜韧带" }, latinName: "Ligamentum popliteum obliquum",
        note: { vi: "Dải sợi toả ra từ gân cơ bán màng, chạy chếch lên ngoài để gia cố bao khớp mặt sau — nó chính là SÀN của hố khoeo ở phần trên. Cùng dây chằng khoeo cung, nó là hàng phòng thủ chống duỗi quá mức của gối. Vì bó mạch khoeo áp thẳng lên dây chằng này, khối u hay phình mạch ở đây đẩy vào nhau rất khó phân biệt trên khám lâm sàng.", en: "A fibrous expansion from the semimembranosus tendon running up and laterally to reinforce the posterior capsule — it is the FLOOR of the upper fossa. With the arcuate ligament it resists knee hyperextension. Because the popliteal vessels lie directly on it, a mass and an aneurysm here are hard to tell apart clinically.", zh: "自半膜肌腱扩展的纤维束，向外上斜行加强后关节囊——构成腘窝上部的底。与腘弓状韧带共同抵抗膝过伸。因腘血管直接贴附其上，此处肿物与动脉瘤在体检时难以鉴别。" } },
      { key: "arcuate-popliteal", meshName: "Arcuate popliteal ligament.r", offset: [0, 0], label: { vi: "Dây chằng khoeo cung", en: "Arcuate popliteal ligament", zh: "腘弓状韧带" }, latinName: "Ligamentum popliteum arcuatum",
        note: { vi: "Bắc hình cung qua gân cơ khoeo ở góc sau ngoài khớp gối, thuộc nhóm cấu trúc giữ vững GÓC SAU NGOÀI. Tổn thương nhóm này ít gặp nhưng hay bị bỏ sót, và nếu bỏ sót thì mảnh ghép dây chằng chéo sau đặt sau đó sẽ giãn dần rồi thất bại — nên khám gối sau chấn thương luôn phải đánh giá riêng góc sau ngoài.", en: "Arches over the popliteus tendon at the posterolateral corner of the knee, part of the POSTEROLATERAL CORNER complex. Injuries here are uncommon but frequently missed, and a missed lesion causes any subsequent posterior cruciate graft to stretch and fail — so the posterolateral corner must be assessed separately after knee trauma.", zh: "于膝后外侧角呈弓状跨过腘肌腱，属后外侧角复合结构。此处损伤不常见却常被漏诊，漏诊将导致其后植入的后交叉韧带移植物逐渐松弛失效——故膝外伤后须单独评估后外侧角。" } },
    ],
  },

  "tam-giac-co": {
    slug: "tam-giac-co",
    title: { vi: "Các tam giác cổ", en: "Triangles of the Neck", zh: "颈部三角" },
    description: {
      vi: "Cổ được chia thành các tam giác giải phẫu bởi một cơ duy nhất: cơ ức đòn chũm. Mọi thứ trước cơ là tam giác trước, mọi thứ sau cơ là tam giác sau — cách chia đơn giản đó lại quyết định cả chẩn đoán lẫn phẫu thuật, vì mỗi tam giác chứa những cấu trúc rất khác nhau và một khối u ở mỗi bên có ý nghĩa khác hẳn. Tam giác trước chứa bó mạch cảnh, tuyến giáp và đường thở; tam giác sau chứa thần kinh phụ, đám rối cánh tay và các hạch dễ sờ thấy. Cổ là vùng nhiều cấu trúc sống còn nằm nông nhất cơ thể, nên mọi vết thương ở đây đều được coi là nặng cho tới khi chứng minh ngược lại.",
      en: "The neck is divided into anatomical triangles by one muscle: sternocleidomastoid. Everything in front of it is the anterior triangle, everything behind it the posterior triangle — a simple division that governs both diagnosis and surgery, because each contains very different structures and a lump in each means something different. The anterior triangle holds the carotid sheath, thyroid and airway; the posterior holds the accessory nerve, brachial plexus and readily palpable nodes.",
      zh: "颈部由胸锁乳突肌一块肌肉划分为解剖三角。其前方为颈前三角，后方为颈后三角——这一简单划分决定了诊断与手术，因两者所含结构迥异，同一肿块在不同三角内意义截然不同。前三角含颈动脉鞘、甲状腺与气道；后三角含副神经、臂丛及易触及的淋巴结。",
    },
    visibleSystems: ["muscular"],
    modelFile: "/models/neck_triangles.glb",
    hotspots: [
      { key: "sternocleidomastoid", meshName: "Sternocleidomastoid muscle.r", offset: [0, 0], label: { vi: "Cơ ức đòn chũm", en: "Sternocleidomastoid", zh: "胸锁乳突肌" }, latinName: "Musculus sternocleidomastoideus",
        note: { vi: "Cơ mốc của toàn vùng cổ, chia cổ thành tam giác TRƯỚC và tam giác SAU. Nó do thần kinh phụ chi phối vận động — một dây thần kinh SỌ chi phối cơ ở cổ, điều bất thường giải thích được bằng nguồn gốc phôi thai của cơ. Co một bên thì quay mặt sang bên ĐỐI DIỆN và nghiêng đầu về cùng bên; xơ hoá cơ ở trẻ sơ sinh gây vẹo cổ với tư thế đúng như vậy.", en: "The landmark muscle of the neck, dividing it into ANTERIOR and POSTERIOR triangles. It is supplied by the accessory nerve — a CRANIAL nerve supplying a neck muscle, an oddity explained by its embryonic origin. One-sided contraction turns the face to the OPPOSITE side and tilts the head to the same side; congenital fibrosis produces torticollis in exactly that posture.", zh: "颈部的标志肌，将颈分为前、后三角。由副神经支配运动——一条脑神经支配颈部肌肉，此特殊现象源于其胚胎起源。单侧收缩使面转向对侧、头倾向同侧；先天性纤维化即致该姿势的斜颈。" } },
      { key: "common-carotid", meshName: "Right common carotid artery.001", offset: [0, 0], label: { vi: "Động mạch cảnh chung", en: "Common carotid artery", zh: "颈总动脉" }, latinName: "Arteria carotis communis",
        note: { vi: "Đi lên trong bao cảnh cùng tĩnh mạch cảnh trong và thần kinh lang thang, chia đôi ở ngang bờ trên sụn giáp (mức C4). Chỗ chia đôi phình ra thành XOANG CẢNH chứa thụ thể áp lực: ép mạnh vào đây làm chậm nhịp tim và tụt huyết áp, nên không được ép hai bên cùng lúc khi khám. Mảng xơ vữa tại chỗ chia đôi là nguồn thuyên tắc gây đột quỵ hay gặp nhất.", en: "Ascends in the carotid sheath with the internal jugular vein and vagus nerve, dividing at the upper border of the thyroid cartilage (C4). The bifurcation dilates into the CAROTID SINUS containing baroreceptors: firm pressure slows the heart and drops the blood pressure, so both sides must never be compressed together. Plaque at this bifurcation is the commonest embolic source of stroke.", zh: "与颈内静脉、迷走神经共行于颈动脉鞘内上行，于甲状软骨上缘（C4）分叉。分叉处膨大为颈动脉窦，内含压力感受器：用力按压可致心率减慢与血压下降，故切忌双侧同时压迫。此分叉处斑块是脑卒中最常见的栓子来源。" } },
      { key: "internal-jugular", meshName: "Internal jugular vein.r.001", offset: [0, 0], label: { vi: "Tĩnh mạch cảnh trong", en: "Internal jugular vein", zh: "颈内静脉" }, latinName: "Vena jugularis interna",
        note: { vi: "Nằm NGOÀI động mạch cảnh trong bao cảnh, là đích của mọi đường đặt catheter tĩnh mạch trung tâm ở cổ. Mốc chọc kim là đỉnh tam giác do hai đầu cơ ức đòn chũm tạo nên. Vì nối trực tiếp với xoang màng cứng và không có van ở đoạn trên, sóng áp lực nhĩ phải truyền ngược lên thành mạch đập tĩnh mạch cổ — dấu hiệu đánh giá suy tim phải tại giường.", en: "Lies LATERAL to the carotid artery within the sheath and is the target of central venous cannulation in the neck, entered at the apex of the triangle between the two heads of sternocleidomastoid. Connected directly to the dural sinuses and valveless proximally, it transmits right atrial pressure waves as the jugular venous pulse — the bedside sign of right heart failure.", zh: "位于鞘内颈动脉外侧，是颈部中心静脉置管的目标，穿刺点取胸锁乳突肌两头之间的三角尖。因直接与硬脑膜窦相通且上段无瓣膜，右房压力波上传形成颈静脉搏动——床旁评估右心衰的体征。" } },
      { key: "vagus-neck", meshName: "Vagus nerve (X).r.001", offset: [0, 0], label: { vi: "Thần kinh lang thang (X)", en: "Vagus nerve", zh: "迷走神经" }, latinName: "Nervus vagus",
        note: { vi: "Thành phần thứ ba của bao cảnh, nằm ở góc SAU giữa động mạch và tĩnh mạch. Ở cổ nó cho nhánh thanh quản trên và, bên phải, quặt ngược quanh động mạch dưới đòn thành dây thanh quản quặt ngược. Vị trí nằm sau khiến nó ít bị tổn thương khi chọc tĩnh mạch cảnh, nhưng lại luôn phải nhận diện khi bóc tách bao cảnh trong mổ hạch cổ.", en: "The third occupant of the carotid sheath, in the POSTERIOR angle between artery and vein. In the neck it gives the superior laryngeal nerve and, on the right, hooks round the subclavian artery as the recurrent laryngeal nerve. Its posterior position spares it during jugular puncture, but it must always be identified when opening the sheath in neck dissection.", zh: "颈动脉鞘的第三个内容物，位于动脉与静脉之间的后角。在颈部发出喉上神经；右侧绕锁骨下动脉返折成喉返神经。其偏后的位置使颈静脉穿刺时不易损伤，但颈清扫打开鞘时必须辨认。" } },
      { key: "accessory-nerve-neck", meshName: "Accessory nerve (XI).r.001", offset: [0, 0], label: { vi: "Thần kinh phụ (XI)", en: "Accessory nerve", zh: "副神经" }, latinName: "Nervus accessorius",
        note: { vi: "Băng qua TAM GIÁC SAU một cách rất nông — chỉ nằm dưới da và mạc, không có cơ nào che. Đó là lý do sinh thiết hạch ở tam giác sau là nguyên nhân hàng đầu gây liệt dây này do thầy thuốc: người bệnh mất khả năng nhún vai, xương bả vai trượt xuống ngoài và đau vai mạn tính. Mốc tìm dây: điểm nối một phần ba trên và hai phần ba dưới bờ sau cơ ức đòn chũm.", en: "Crosses the POSTERIOR TRIANGLE extremely superficially — under skin and fascia only, covered by no muscle. Lymph node biopsy in this triangle is therefore the leading iatrogenic cause of accessory nerve palsy: loss of shoulder shrug, a drooping laterally displaced scapula and chronic shoulder pain. It emerges at the junction of the upper third and lower two thirds of the posterior border of sternocleidomastoid.", zh: "极表浅地横过颈后三角——仅覆以皮肤与筋膜，无肌肉遮盖。故该三角内淋巴结活检是副神经医源性损伤的首要原因：耸肩不能、肩胛骨下垂外移、慢性肩痛。定位标志为胸锁乳突肌后缘上1/3与下2/3交界处。" } },
      { key: "omohyoid", meshName: "Omohyoid muscle.r", offset: [0, 0], label: { vi: "Cơ vai móng", en: "Omohyoid", zh: "肩胛舌骨肌" }, latinName: "Musculus omohyoideus",
        note: { vi: "Cơ hai bụng nối bởi một gân trung gian, bắc chéo qua cổ như một cái cầu và CHIA NHỎ cả hai tam giác lớn: bụng trên chia tam giác trước thành tam giác cảnh và tam giác cơ, bụng dưới chia tam giác sau thành tam giác chẩm và tam giác trên đòn. Trong mổ, nó là mốc dễ nhận để biết mình đang ở tầng nào của cổ.", en: "A two-bellied muscle joined by an intermediate tendon, crossing the neck like a bridge and SUBDIVIDING both major triangles: its superior belly splits the anterior triangle into carotid and muscular triangles, its inferior belly splits the posterior into occipital and supraclavicular triangles. In surgery it is an easily recognised level marker.", zh: "由中间腱连接的二腹肌，如桥梁般斜跨颈部并再分两大三角：上腹将前三角分为颈动脉三角与肌三角，下腹将后三角分为枕三角与锁骨上三角。手术中是易辨认的层次标志。" } },
      { key: "thyroid-neck", meshName: "Thyroid gland", offset: [0, 0], label: { vi: "Tuyến giáp", en: "Thyroid gland", zh: "甲状腺" }, latinName: "Glandula thyroidea",
        note: { vi: "Nằm trong tam giác cơ, ôm hai bên khí quản. Vì được bọc trong bao trước khí quản dính vào thanh quản nên tuyến DI ĐỘNG THEO NHỊP NUỐT — dấu hiệu khám phân biệt khối tuyến giáp với mọi khối khác ở cổ. Mặt sau tuyến áp sát dây thanh quản quặt ngược và bốn tuyến cận giáp, hai thứ quyết định biến chứng của mọi ca cắt tuyến giáp.", en: "Sits in the muscular triangle astride the trachea. Enclosed in pretracheal fascia attached to the larynx, it MOVES ON SWALLOWING — the sign separating a thyroid mass from any other neck lump. Its posterior surface abuts the recurrent laryngeal nerve and the four parathyroids, the two structures that define the complications of thyroidectomy.", zh: "位于肌三角内，夹持气管。因包于附着喉部的气管前筋膜内，随吞咽上下移动——是鉴别甲状腺肿块与其他颈部肿块的体征。其后面紧邻喉返神经与四个甲状旁腺，二者决定了甲状腺手术的并发症。" } },
      { key: "external-jugular", meshName: "External jugular vein.r.001", offset: [0, 0], label: { vi: "Tĩnh mạch cảnh ngoài", en: "External jugular vein", zh: "颈外静脉" }, latinName: "Vena jugularis externa",
        note: { vi: "Chạy CHÉO qua mặt ngoài cơ ức đòn chũm ngay dưới lớp cơ bám da cổ, là tĩnh mạch cổ duy nhất nhìn thấy được qua da. Vì bị mạc cổ giữ chặt ở chỗ xuyên qua để đổ vào tĩnh mạch dưới đòn, vết rách ở đó KHÔNG XẸP được và có thể hút khí vào gây tắc mạch khí — lý do vết thương vùng cổ luôn được băng kín ngay.", en: "Runs OBLIQUELY across the surface of sternocleidomastoid beneath platysma and is the only neck vein visible through the skin. Because the cervical fascia holds it open where it pierces to join the subclavian vein, a laceration there CANNOT COLLAPSE and may entrain air — the reason neck wounds are sealed immediately.", zh: "在颈阔肌深面斜过胸锁乳突肌表面，是唯一可透皮看见的颈静脉。因其穿筋膜汇入锁骨下静脉处被固定张开，该处裂伤不能塌陷并可吸入空气致气栓——故颈部伤口须立即封闭。" } },
      { key: "trachea-neck", meshName: "Trachea", offset: [0, 0], label: { vi: "Khí quản (đoạn cổ)", en: "Cervical trachea", zh: "颈段气管" }, latinName: "Trachea",
        note: { vi: "Nằm chính giữa tam giác cơ, ngay dưới eo tuyến giáp là các vòng sụn 2–4. Đó là lý do mở khí quản cấp cứu thường vào ở vòng 2–3 và có khi phải cắt eo tuyến giáp. Ở trên cao hơn, màng nhẫn giáp nằm nông và không có mạch lớn che nên là chỗ chọc kim cấp cứu khi tắc đường thở trên — nhanh và an toàn hơn mở khí quản trong tình huống nguy kịch.", en: "Lies in the midline of the muscular triangle, with rings 2–4 just deep to the thyroid isthmus — which is why emergency tracheostomy enters at rings 2–3 and may require dividing the isthmus. Higher up the cricothyroid membrane is superficial and free of large vessels, making it the site for emergency needle access in upper airway obstruction.", zh: "位于肌三角中线，甲状腺峡部深面为第2–4气管环——故急诊气管切开多在第2–3环，有时需切断峡部。更上方的环甲膜表浅且无大血管，是上气道梗阻时紧急穿刺的部位。" } },
    ],
  },

  "khoang-sau-phuc-mac": {
    slug: "khoang-sau-phuc-mac",
    title: { vi: "Khoang sau phúc mạc", en: "The Retroperitoneum", zh: "腹膜后间隙" },
    description: {
      vi: "Khoang nằm giữa phúc mạc thành sau và thành bụng sau — nơi chứa thận, niệu quản, tuyến thượng thận cùng hai mạch lớn nhất cơ thể. Đặc điểm quyết định của khoang này là nó KÍN và KHÔNG CÓ MẠC NỐI để khu trú tổn thương như trong ổ phúc mạc, nên chảy máu ở đây có thể lên tới vài lít mà bụng vẫn mềm và không có phản ứng thành bụng. Đó là lý do vỡ phình động mạch chủ bụng hay bị chẩn đoán muộn: người bệnh đau lưng, tụt huyết áp, mà khám bụng gần như bình thường. Cũng vì nằm ngoài phúc mạc mà thận có thể mổ từ đường lưng không cần mở ổ bụng.",
      en: "The space between the posterior parietal peritoneum and the posterior abdominal wall, holding the kidneys, ureters, adrenals and the body's two largest vessels. Its defining feature is that it is CLOSED and has no omentum to wall off injury as the peritoneal cavity does — so bleeding here can reach litres while the abdomen stays soft and without guarding. That is why ruptured abdominal aortic aneurysm is diagnosed late: back pain and hypotension with an almost normal abdominal examination.",
      zh: "位于壁腹膜后层与腹后壁之间的间隙，容纳肾、输尿管、肾上腺及全身最大的两条血管。其决定性特点是封闭且无大网膜包裹损伤，故此处出血可达数升而腹部仍柔软、无肌紧张。这正是腹主动脉瘤破裂常延误诊断的原因：腰背痛、低血压而腹部检查近乎正常。",
    },
    visibleSystems: ["visceral"],
    modelFile: "/models/retroperitoneum.glb",
    hotspots: [
      { key: "kidney-retro", meshName: "Kidney.r", offset: [0, 0], label: { vi: "Thận", en: "Kidney", zh: "肾" }, latinName: "Ren",
        note: { vi: "Nằm hai bên cột sống ngang mức T12–L3, thận PHẢI thấp hơn thận trái chừng nửa đốt sống vì bị gan đè lên. Quanh thận có ba lớp bọc: bao xơ, lớp mỡ quanh thận rồi mạc thận — chính lớp mỡ này làm thận nổi rõ trên phim bụng không chuẩn bị và cũng là lớp đệm khiến thận chịu được chấn thương khá tốt. Thận di động lên xuống chừng 2–3 cm theo nhịp thở.", en: "Lies beside the vertebral column at T12–L3, the RIGHT kidney sitting about half a vertebra lower because of the liver. Three coverings surround it: capsule, perirenal fat, then renal fascia — the fat outlines the kidney on a plain film and cushions it against trauma. The kidney moves 2–3 cm with respiration.", zh: "位于脊柱两侧T12–L3平面，右肾因肝脏推压而低于左肾约半个椎体。周围有三层被膜：纤维囊、肾周脂肪、肾筋膜——脂肪层使肾在腹部平片上显影，并缓冲外伤。肾随呼吸上下移动2–3厘米。" } },
      { key: "renal-pelvis", meshName: "Renal pelvis.r", offset: [0, 0], label: { vi: "Bể thận", en: "Renal pelvis", zh: "肾盂" }, latinName: "Pelvis renalis",
        note: { vi: "Phễu gom nước tiểu từ các đài thận rồi thu hẹp lại thành niệu quản. Chỗ nối bể thận – niệu quản là điểm HẸP THỨ NHẤT trên đường tiết niệu, nên sỏi hay mắc lại đây. Hẹp bẩm sinh chỗ nối này gây ứ nước thận tiến triển âm thầm ở trẻ, phát hiện muộn thì nhu mô thận đã mỏng đi không hồi phục.", en: "The funnel collecting urine from the calices before narrowing into the ureter. The pelvi-ureteric junction is the FIRST narrowing of the urinary tract, where stones commonly lodge. Congenital stenosis here causes silently progressive hydronephrosis in children, with irreversible parenchymal thinning if found late.", zh: "汇集肾盏尿液的漏斗，继而缩窄为输尿管。肾盂输尿管连接部是尿路第一处狭窄，结石常嵌顿于此。此处先天性狭窄致儿童隐匿进展的肾积水，发现过晚则肾实质变薄不可逆。" } },
      { key: "ureter-retro", meshName: "Ureter.r.001", offset: [0, 0], label: { vi: "Niệu quản", en: "Ureter", zh: "输尿管" }, latinName: "Ureter",
        note: { vi: "Ống cơ dài chừng 25 cm chạy sát mặt trước cơ thắt lưng lớn xuống chậu hông. Nó có BA CHỖ HẸP: chỗ nối bể thận, chỗ bắt chéo mạch chậu và chỗ chui vào thành bàng quang — sỏi kẹt ở đâu thì đau lan theo đúng khoanh da tương ứng, từ hông lưng xuống bẹn rồi tới bìu hoặc môi lớn. Trên phim, niệu quản chạy dọc theo mỏm ngang các đốt thắt lưng.", en: "A 25 cm muscular tube running on the front of psoas major into the pelvis. It has THREE NARROWINGS: the pelvi-ureteric junction, the crossing of the iliac vessels and the passage through the bladder wall — a stone at each refers pain along its own dermatome, from loin to groin to scrotum or labium. Radiographically it follows the lumbar transverse processes.", zh: "长约25厘米的肌性管道，沿腰大肌前面下行入盆。有三处狭窄：肾盂输尿管连接部、跨髂血管处、穿膀胱壁处——结石嵌顿于各处则沿相应皮节放射痛，自腰部至腹股沟再至阴囊或大阴唇。影像上沿腰椎横突走行。" } },
      { key: "suprarenal-retro", meshName: "Suprarenal gland.r", offset: [0, 0], label: { vi: "Tuyến thượng thận", en: "Suprarenal gland", zh: "肾上腺" }, latinName: "Glandula suprarenalis",
        note: { vi: "Đội trên cực trên thận, nhưng nằm trong một ngăn riêng của mạc thận nên khi thận sa xuống tuyến vẫn ở nguyên chỗ. Tuyến này được cấp máu bởi ba nguồn riêng biệt — từ động mạch hoành dưới, động mạch chủ và động mạch thận — nhưng chỉ có MỘT tĩnh mạch duy nhất, chi tiết rất quan trọng khi mổ cắt tuyến vì thắt nhầm hoặc làm rách tĩnh mạch đó là chảy máu khó kiểm soát.", en: "Caps the upper pole of the kidney but sits in its own compartment of renal fascia, so it stays put if the kidney drops. It has three separate arterial supplies — inferior phrenic, aorta and renal artery — but only ONE vein, a detail that matters in adrenalectomy since tearing it causes bleeding that is hard to control.", zh: "覆于肾上极，但位于肾筋膜的独立分隔内，故肾下垂时其位置不变。有三个独立动脉来源——膈下动脉、主动脉与肾动脉——却仅有一条静脉，此细节在肾上腺切除术中至关重要，撕裂该静脉将致难以控制的出血。" } },
      { key: "abdominal-aorta-retro", meshName: "Abdominal aorta.001", offset: [0, 0], label: { vi: "Động mạch chủ bụng", en: "Abdominal aorta", zh: "腹主动脉" }, latinName: "Aorta abdominalis",
        note: { vi: "Đi xuống hơi LỆCH TRÁI đường giữa, từ chỗ chui qua cơ hoành ở mức T12 tới chỗ chia đôi ở mức L4. Đường kính bình thường ở người trưởng thành khoảng 2 cm; giãn quá 3 cm gọi là phình, quá 5,5 cm thì nguy cơ vỡ vượt nguy cơ mổ. Vì nằm sau phúc mạc, khối phình đập theo nhịp tim sờ được ở trên rốn hơi lệch trái, và khi vỡ máu tràn vào khoang sau phúc mạc chứ không vào ổ bụng.", en: "Descends slightly LEFT of the midline from the diaphragmatic hiatus at T12 to its bifurcation at L4. Normal adult diameter is about 2 cm; over 3 cm is an aneurysm and beyond 5.5 cm the rupture risk exceeds the operative risk. Being retroperitoneal, an aneurysm is felt as an expansile pulsation above and left of the umbilicus, and when it ruptures blood fills the retroperitoneum rather than the peritoneal cavity.", zh: "略偏中线左侧下行，自T12膈主动脉裂孔至L4分叉。成人正常直径约2厘米；超过3厘米为动脉瘤，超过5.5厘米时破裂风险高于手术风险。因位于腹膜后，动脉瘤可在脐上偏左触及膨胀性搏动；破裂时血液充盈腹膜后间隙而非腹腔。" } },
      { key: "ivc-retro", meshName: "Inferior vena cava (abdominal part).001", offset: [0, 0], label: { vi: "Tĩnh mạch chủ dưới", en: "Inferior vena cava", zh: "下腔静脉" }, latinName: "Vena cava inferior",
        note: { vi: "Nằm BÊN PHẢI động mạch chủ, do hai tĩnh mạch chậu chung hợp lại ở mức L5. Thành mỏng và áp lực thấp nên nó bị mọi thứ xung quanh ép: khối u sau phúc mạc, tử cung to ở thai phụ nằm ngửa, hay chính ống nội soi khi bơm hơi ổ bụng. Vị trí lệch phải là lý do tĩnh mạch thận trái phải bắc ngang qua trước động mạch chủ mới sang được.", en: "Lies to the RIGHT of the aorta, formed by the two common iliac veins at L5. Thin-walled and low-pressure, it is compressed by everything around it: retroperitoneal tumours, the gravid uterus in a supine woman, even laparoscopic insufflation. Its rightward position is why the left renal vein must cross in front of the aorta.", zh: "位于主动脉右侧，由两侧髂总静脉于L5汇成。壁薄压力低，易受周围结构压迫：腹膜后肿瘤、仰卧孕妇的增大子宫，乃至腹腔镜气腹。其偏右的位置正是左肾静脉须跨越主动脉前方的原因。" } },
      { key: "psoas-retro", meshName: "Psoas major.r", offset: [0, 0], label: { vi: "Cơ thắt lưng lớn", en: "Psoas major", zh: "腰大肌" }, latinName: "Musculus psoas major",
        note: { vi: "Tạo thành gờ dọc hai bên cột sống, là NỀN mà niệu quản trượt trên đó và là bờ ngoài của khoang sau phúc mạc. Bờ ngoài cơ hiện rõ trên phim bụng không chuẩn bị; mất bờ cơ thắt lưng một bên là dấu hiệu gián tiếp của khối máu tụ hoặc áp-xe sau phúc mạc. Áp-xe lao cột sống chảy dọc theo bao cơ xuống tận tam giác đùi.", en: "Forms a ridge either side of the vertebral column, the BED on which the ureter glides and the lateral boundary of the retroperitoneum. Its lateral border is visible on a plain abdominal film; loss of the psoas outline is an indirect sign of retroperitoneal haematoma or abscess. Tuberculous spinal abscess tracks down its sheath as far as the femoral triangle.", zh: "在脊柱两侧形成隆嵴，是输尿管滑行的床，也是腹膜后间隙的外侧界。其外侧缘在腹部平片上可见；一侧腰大肌影消失是腹膜后血肿或脓肿的间接征象。脊柱结核脓肿可沿其鞘下流至股三角。" } },
      { key: "quadratus-lumborum-retro", meshName: "Quadratus lumborum muscle.r", offset: [0, 0], label: { vi: "Cơ vuông thắt lưng", en: "Quadratus lumborum", zh: "腰方肌" }, latinName: "Musculus quadratus lumborum",
        note: { vi: "Cơ hình tứ giác nối xương sườn XII với mào chậu, nằm ngay SAU thận nên tạo thành thành sau của khoang. Nó kéo xương sườn XII xuống để cố định điểm tựa cho cơ hoành khi hít vào — nghĩa là một cơ thành bụng lại tham gia vào động tác thở. Co thắt cơ này là nguyên nhân thường gặp của đau thắt lưng một bên bị chẩn đoán nhầm thành bệnh thận.", en: "A quadrilateral muscle from the twelfth rib to the iliac crest, lying directly BEHIND the kidney and forming the posterior wall of the space. It pulls the twelfth rib down to fix the diaphragm's origin during inspiration — an abdominal wall muscle that participates in breathing. Its spasm is a common cause of unilateral loin pain misdiagnosed as renal disease.", zh: "自第12肋至髂嵴的四边形肌，紧邻肾后方，构成本间隙的后壁。吸气时下拉第12肋以固定膈的起点——腹壁肌却参与呼吸。其痉挛是单侧腰痛的常见原因，常被误诊为肾脏疾病。" } },
      { key: "lumbar-vertebra-retro", meshName: "Vertebra L1", offset: [0, 0], label: { vi: "Đốt sống thắt lưng I", en: "First lumbar vertebra", zh: "第一腰椎" }, latinName: "Vertebra lumbalis I",
        note: { vi: "Mức L1 là MẶT PHẲNG MỐC quan trọng nhất của ổ bụng: rốn tuỷ sống kết thúc ở đây ở người lớn, động mạch mạc treo tràng trên tách ra ở đây, và mặt phẳng ngang qua đây (mặt phẳng môn vị) đi qua môn vị, cổ tuỵ và rốn thận. Nhớ một mức đốt sống này là định vị được gần như mọi cấu trúc sau phúc mạc trên phim cắt lớp.", en: "L1 is the most useful abdominal LANDMARK PLANE: the spinal cord ends here in adults, the superior mesenteric artery arises here, and the transpyloric plane through it crosses the pylorus, neck of pancreas and renal hila. Remembering this single level locates almost every retroperitoneal structure on cross-sectional imaging.", zh: "L1是腹部最有用的标志平面：成人脊髓终止于此，肠系膜上动脉发自此处，经此的幽门平面横过幽门、胰颈与肾门。记住这一椎体平面，即可在断层影像上定位几乎所有腹膜后结构。" } },
    ],
  },

  "khop-khuyu": {
    slug: "khop-khuyu",
    title: { vi: "Khớp khuỷu", en: "The Elbow Joint", zh: "肘关节" },
    description: {
      vi: "Khớp khuỷu thật ra là BA khớp nằm chung một bao: khớp cánh tay – trụ và cánh tay – quay lo gấp duỗi, còn khớp quay – trụ trên lo sấp ngửa. Ba khớp chung một ổ nghĩa là tràn dịch ở bất kỳ khớp nào cũng làm phồng cả ổ, và tư thế giảm đau chung là gấp khoảng 70 độ — tư thế mà ổ khớp có thể tích lớn nhất. Điểm cần thuộc nhất là ba mốc xương: mỏm trên lồi cầu trong, mỏm trên lồi cầu ngoài và mỏm khuỷu tạo thành TAM GIÁC đều khi gấp khuỷu và thành đường thẳng khi duỗi — mất tương quan này là trật khớp, còn giữ nguyên mà vẫn đau nhiều thì nghĩ tới gãy trên lồi cầu.",
      en: "The elbow is really THREE joints in one capsule: humero-ulnar and humero-radial for flexion and extension, and the superior radio-ulnar for pronation and supination. Sharing one cavity means an effusion anywhere distends the whole joint, and the common position of ease is about 70° of flexion, where capacity is greatest. The essential landmarks are three bony points: medial epicondyle, lateral epicondyle and olecranon, forming an equilateral TRIANGLE in flexion and a straight line in extension — loss of that relationship means dislocation.",
      zh: "肘实为共处一囊的三个关节：肱尺与肱桡关节司屈伸，上尺桡关节司旋前旋后。共用一个关节腔意味着任一处积液均使整个关节膨隆，共同的舒适位为屈曲约70度，此时关节容积最大。最须掌握的是三个骨性标志：内上髁、外上髁与鹰嘴，屈肘时构成等边三角形，伸肘时呈一直线——此关系丧失即为脱位。",
    },
    visibleSystems: ["skeletal"],
    modelFile: "/models/elbow_joint.glb",
    hotspots: [
      { key: "humerus-elbow", meshName: "Humerus.r", offset: [0, 0], label: { vi: "Xương cánh tay (đầu dưới)", en: "Humerus, distal end", zh: "肱骨下端" }, latinName: "Humerus",
        note: { vi: "Đầu dưới bè ra thành hai lồi cầu với ròng rọc ở trong và chỏm con ở ngoài. Vùng trên lồi cầu là chỗ MỎNG NHẤT của xương, nên gãy trên lồi cầu là gãy hay gặp nhất ở trẻ em khi ngã chống tay. Đầu gãy di lệch ra sau có thể ép động mạch cánh tay và thần kinh giữa — luôn phải bắt mạch quay và thử vận động ngón trước khi nắn.", en: "The distal end flares into two condyles, with the trochlea medially and the capitulum laterally. The supracondylar region is the THINNEST part of the bone, making supracondylar fracture the commonest childhood elbow injury after a fall on the outstretched hand. Posterior displacement can compress the brachial artery and median nerve — always check the radial pulse and finger movement before reduction.", zh: "下端膨大为两个髁，内侧为滑车，外侧为肱骨小头。髁上区为骨质最薄处，故髁上骨折是儿童跌倒撑地后最常见的肘部损伤。断端向后移位可压迫肱动脉与正中神经——复位前必须检查桡动脉搏动与手指活动。" } },
      { key: "annular-ligament", meshName: "Annular ligament of radius.r", offset: [0, 0], label: { vi: "Dây chằng vòng quay", en: "Annular ligament of the radius", zh: "桡骨环状韧带" }, latinName: "Ligamentum anulare radii",
        note: { vi: "Vòng sợi ôm quanh chỏm xương quay, giữ chỏm áp vào khuyết quay của xương trụ trong khi vẫn cho chỏm XOAY tự do khi sấp ngửa. Ở trẻ nhỏ chỏm quay còn tròn và nhỏ nên chỉ cần kéo mạnh cẳng tay khi trẻ đang duỗi sấp là chỏm tuột ra khỏi vòng — đó chính là bán trật chỏm quay hay gọi là “khuỷu tay bảo mẫu”, nắn lại chỉ mất vài giây.", en: "A fibrous ring encircling the radial head, holding it against the radial notch of the ulna while allowing free ROTATION in pronation and supination. In small children the head is still round and small, so a sharp pull on the pronated extended forearm slips it out of the ring — the pulled elbow of childhood, reduced in seconds.", zh: "环绕桡骨头的纤维环，将其固定于尺骨桡切迹，同时允许旋前旋后时自由旋转。幼儿桡骨头尚圆而小，前臂旋前伸直位被猛拉即可自环内滑脱——即牵拉肘，复位仅需数秒。" } },
      { key: "elbow-capsule", meshName: "Articular capsule of elbow joint.r", offset: [0, 0], label: { vi: "Bao khớp khuỷu", en: "Capsule of the elbow joint", zh: "肘关节囊" }, latinName: "Capsula articularis cubiti",
        note: { vi: "Bao chung cho cả ba khớp, mỏng ở trước và sau để cho phép gấp duỗi, nhưng dày lên hai bên thành dây chằng bên trong và bên ngoài. Vì mỏng ở sau, tràn dịch khớp đẩy lớp mỡ sau ra và cho DẤU HIỆU MỠ SAU trên phim nghiêng — dấu hiệu gián tiếp của gãy xương kín mà phim thẳng không thấy đường gãy.", en: "A single capsule for all three joints, thin in front and behind to permit flexion but thickened at the sides into the collateral ligaments. Because it is thin posteriorly, an effusion displaces the posterior fat pad and produces the POSTERIOR FAT PAD SIGN on the lateral film — indirect evidence of an occult fracture.", zh: "三个关节共用一个关节囊，前后薄以利屈伸，两侧增厚为侧副韧带。因后方薄弱，积液使后脂肪垫移位，侧位片出现后脂肪垫征——隐匿性骨折的间接证据。" } },
      { key: "ulnar-nerve-elbow", meshName: "Ulnar nerve.r.001", offset: [0, 0], label: { vi: "Thần kinh trụ (rãnh sau mỏm trên lồi cầu trong)", en: "Ulnar nerve in the cubital tunnel", zh: "尺神经（肘管内）" }, latinName: "Nervus ulnaris",
        note: { vi: "Chạy trong rãnh ngay SAU mỏm trên lồi cầu trong, chỉ có da che — đây là “xương cười”, gõ vào thì tê buốt lan xuống ngón út. Vì nằm nông và bị kéo căng mỗi khi gấp khuỷu, đây là nơi dây trụ hay bị chèn ép thứ hai sau ống Guyon: hội chứng ống khuỷu gây tê ngón út và bờ trong bàn tay, nặng thì teo cơ gian cốt và bàn tay vuốt trụ.", en: "Runs in a groove directly BEHIND the medial epicondyle covered only by skin — the 'funny bone', which tingles into the little finger when struck. Superficial and stretched with every elbow flexion, this is the second commonest site of ulnar compression after Guyon's canal: cubital tunnel syndrome numbs the little finger and ulnar border, and in advanced cases wastes the interossei into an ulnar claw.", zh: "行于内上髁正后方的沟内，仅覆皮肤——即“麻筋”，叩击时小指麻痛。位置浅表且屈肘时受牵拉，是仅次于Guyon管的尺神经第二常见卡压部位：肘管综合征致小指与手尺侧麻木，重者骨间肌萎缩形成爪形手。" } },
      { key: "median-nerve-elbow", meshName: "Median nerve.r.001", offset: [0, 0], label: { vi: "Thần kinh giữa", en: "Median nerve", zh: "正中神经" }, latinName: "Nervus medianus",
        note: { vi: "Đi ở mặt TRƯỚC khuỷu, nằm TRONG so với động mạch cánh tay trong hố khuỷu. Xa hơn một chút nó chui giữa hai đầu cơ sấp tròn — chỗ hẹp gây hội chứng cơ sấp tròn, khác hội chứng ống cổ tay ở chỗ có tê cả vùng ô mô cái vì nhánh gan tay tách ra trước ống cổ tay. Trong hố khuỷu, thứ tự từ trong ra ngoài là: thần kinh giữa, động mạch, gân cơ nhị đầu.", en: "Runs on the FRONT of the elbow, MEDIAL to the brachial artery in the cubital fossa, then passes between the two heads of pronator teres — the narrowing responsible for pronator syndrome, distinguished from carpal tunnel syndrome by numbness that includes the thenar skin. In the fossa the order from medial to lateral is nerve, artery, biceps tendon.", zh: "行于肘前，在肘窝内位于肱动脉内侧，继而穿旋前圆肌两头之间——此狭窄致旋前圆肌综合征，与腕管综合征的区别在于鱼际皮肤亦麻木。肘窝内由内向外依次为神经、动脉、肱二头肌腱。" } },
      { key: "brachial-artery-elbow", meshName: "Brachial artery.r.001", offset: [0, 0], label: { vi: "Động mạch cánh tay", en: "Brachial artery", zh: "肱动脉" }, latinName: "Arteria brachialis",
        note: { vi: "Nằm giữa hố khuỷu, ngay TRONG gân cơ nhị đầu — đây chính là chỗ đặt ống nghe khi đo huyết áp. Nó chia thành động mạch quay và động mạch trụ ngay dưới nếp khuỷu. Gãy trên lồi cầu di lệch ép mạch này gây thiếu máu cẳng tay; nếu bỏ sót, cơ vùng gấp hoại tử rồi xơ lại thành co rút Volkmann, bàn tay co quắp vĩnh viễn.", en: "Lies in the middle of the cubital fossa just MEDIAL to the biceps tendon — the spot for the stethoscope when taking blood pressure. It divides into radial and ulnar arteries just below the elbow crease. A displaced supracondylar fracture compressing it causes forearm ischaemia; if missed, the flexor muscles necrose and fibrose into Volkmann contracture with a permanently clawed hand.", zh: "位于肘窝中央、肱二头肌腱内侧——即测血压时听诊器放置处。于肘横纹下方分为桡动脉与尺动脉。髁上骨折移位压迫该动脉致前臂缺血；若漏诊，屈肌坏死纤维化形成Volkmann挛缩，手部永久性屈曲畸形。" } },
      { key: "brachialis", meshName: "Brachialis muscle.r", offset: [0, 0], label: { vi: "Cơ cánh tay trước", en: "Brachialis", zh: "肱肌" }, latinName: "Musculus brachialis",
        note: { vi: "Cơ GẤP KHUỶU MẠNH NHẤT, bám tận vào lồi củ xương trụ nên gấp được ở mọi tư thế sấp ngửa — khác cơ nhị đầu vốn yếu hẳn khi cẳng tay sấp. Nó nằm ngay trước bao khớp và là “cơ đệm” của khớp khuỷu. Chấn thương gây tụ máu trong cơ này có thể hoá cốt thành viêm cơ cốt hoá, làm hạn chế gấp duỗi kéo dài — lý do không được xoa bóp mạnh khuỷu sau chấn thương.", en: "The STRONGEST elbow flexor, inserting on the ulnar tuberosity so it flexes in any position of rotation — unlike biceps, which weakens markedly in pronation. It lies directly in front of the capsule as the joint's cushion. A haematoma within it may ossify into myositis ossificans, causing lasting loss of movement — the reason vigorous massage of the injured elbow is contraindicated.", zh: "最强的屈肘肌，止于尺骨粗隆，故在任何旋转位均能屈肘——与旋前时明显减弱的肱二头肌不同。位于关节囊正前方，是肘关节的缓冲垫。其内血肿可骨化为骨化性肌炎，致长期活动受限——故肘外伤后禁忌用力按摩。" } },
      { key: "anconeus", meshName: "Anconeus muscle.r", offset: [0, 0], label: { vi: "Cơ khuỷu", en: "Anconeus", zh: "肘肌" }, latinName: "Musculus anconeus",
        note: { vi: "Cơ tam giác nhỏ ở mặt sau ngoài khuỷu, phụ giúp cơ tam đầu duỗi khuỷu và giữ bao khớp khỏi bị kẹp khi duỗi. Điều làm nó đáng nhớ trên lâm sàng là vị trí: tam giác giữa mỏm khuỷu, mỏm trên lồi cầu ngoài và chỏm quay — phủ bởi chính cơ này — là điểm CHỌC HÚT DỊCH KHỚP KHUỶU an toàn nhất vì không có mạch thần kinh lớn nào đi qua.", en: "A small triangular muscle at the posterolateral elbow assisting triceps in extension and keeping the capsule from being pinched. Its clinical importance is positional: the triangle between olecranon, lateral epicondyle and radial head — covered by this muscle — is the safest point for ELBOW JOINT ASPIRATION, since no major vessel or nerve crosses it.", zh: "肘后外侧的三角形小肌，协助肱三头肌伸肘并防止关节囊被夹。其临床意义在于位置：鹰嘴、外上髁与桡骨头之间的三角区——正由此肌覆盖——是肘关节穿刺最安全的进针点，因无大血管神经通过。" } },
      { key: "radius-elbow", meshName: "Radius.r", offset: [0, 0], label: { vi: "Xương quay (chỏm)", en: "Radius — head", zh: "桡骨头" }, latinName: "Caput radii",
        note: { vi: "Chỏm hình đĩa tiếp khớp với chỏm con xương cánh tay ở trên và với khuyết quay xương trụ ở trong. Ngã chống tay truyền lực dọc trục làm gãy chỏm quay — loại gãy hay gặp nhất ở người lớn tại khuỷu, ngược với gãy trên lồi cầu ở trẻ em. Dấu hiệu sớm là đau chói khi SẤP NGỬA chứ không phải khi gấp duỗi, dễ bị bỏ qua nếu chỉ khám gấp duỗi.", en: "A disc-shaped head articulating with the capitulum above and the ulnar radial notch medially. A fall on the outstretched hand drives it axially and fractures it — the commonest adult elbow fracture, mirroring supracondylar fracture in children. The early sign is sharp pain on PRONATION AND SUPINATION rather than on flexion, easily missed if only flexion is tested.", zh: "盘状的桡骨头，上与肱骨小头、内与尺骨桡切迹相关节。伸手撑地跌倒时轴向传力致桡骨头骨折——成人最常见的肘部骨折，与儿童髁上骨折相对。早期体征为旋前旋后时锐痛而非屈伸痛，仅查屈伸易漏诊。" } },
    ],
  },

  "khop-co-chan": {
    slug: "khop-co-chan",
    title: { vi: "Khớp cổ chân", en: "The Ankle Joint", zh: "踝关节" },
    description: {
      vi: "Khớp cổ chân là một khớp RÒNG RỌC: xương sên bị kẹp giữa hai mắt cá như con quay trong gọng kìm, chỉ cho phép gấp mu và gấp gan chân. Chính cấu tạo gọng kìm ấy giải thích mọi chấn thương ở đây — mặt trên xương sên rộng ở phía TRƯỚC nên khi gấp mu chân, xương sên chèn chặt vào gọng kìm và khớp vững nhất; khi gấp gan chân (kiễng chân, đi giày cao gót) phần hẹp lọt vào gọng kìm, khớp lỏng ra và đó là lúc dễ lật cổ chân nhất. Bên ngoài chỉ có ba dây chằng mảnh, bên trong có một dây chằng delta rất khoẻ — nên lật cổ chân vào trong chiếm khoảng 85% các ca bong gân cổ chân.",
      en: "The ankle is a HINGE joint: the talus is gripped between the two malleoli like a tenon in a mortise, allowing only dorsiflexion and plantarflexion. That mortise explains every injury here — the upper surface of the talus is wider ANTERIORLY, so in dorsiflexion it wedges tightly and the joint is most stable; in plantarflexion (tiptoe, high heels) the narrow part enters the mortise, the joint loosens, and that is when inversion sprains happen. Laterally there are only three slender ligaments against a strong medial deltoid, which is why inversion injuries account for about 85% of ankle sprains.",
      zh: "踝关节为屈戌关节：距骨如榫头被两踝钳夹，仅允许背伸与跖屈。此榫卯结构解释了本区所有损伤——距骨上面前宽后窄，故背伸时紧嵌于榫眼中最为稳定；跖屈时（踮脚、穿高跟鞋）窄部进入榫眼，关节松弛，此时最易发生内翻扭伤。外侧仅有三条纤细韧带，内侧则有强韧的三角韧带，故内翻损伤约占踝扭伤的85%。",
    },
    visibleSystems: ["skeletal"],
    modelFile: "/models/ankle_joint.glb",
    hotspots: [
      { key: "talus", meshName: "Talus.r", offset: [0, 0], label: { vi: "Xương sên", en: "Talus", zh: "距骨" }, latinName: "Talus",
        note: { vi: "Xương duy nhất của bàn chân KHÔNG CÓ CƠ NÀO BÁM VÀO — nó chỉ nhận và truyền lực. Toàn bộ trọng lượng cơ thể đi qua nó xuống xương gót và vòm bàn chân. Mạch nuôi đi vào từ cổ xương sên rồi chảy ngược lên chỏm, nên gãy cổ xương sên cắt đứt nguồn máu và gây hoại tử vô mạch tới một nửa số ca — biến chứng nặng nề vì làm hỏng cả hai khớp mà xương này tham gia.", en: "The only bone in the foot with NO MUSCLE ATTACHMENT — it merely receives and transmits load. The entire body weight passes through it to the calcaneus and the arches. Its blood supply enters at the neck and runs retrograde, so a talar neck fracture causes avascular necrosis in up to half of cases, ruining both joints the bone serves.", zh: "足部唯一无肌肉附着的骨——仅承受与传递负荷。全身体重经其传至跟骨与足弓。血供自距骨颈进入逆行走行，故距骨颈骨折致缺血性坏死者可达半数，并同时破坏其参与的两个关节。" } },
      { key: "anterior-talofibular", meshName: "Anterior talofibular ligament.r", offset: [0, 0], label: { vi: "Dây chằng sên – mác trước", en: "Anterior talofibular ligament", zh: "距腓前韧带" }, latinName: "Ligamentum talofibulare anterius",
        note: { vi: "Dây chằng YẾU NHẤT và bị rách ĐẦU TIÊN trong bong gân cổ chân — nó căng nhất ở tư thế gấp gan chân kèm lật vào trong, đúng tư thế lúc chấn thương xảy ra. Đau chói ngay trước dưới mắt cá ngoài là dấu hiệu kinh điển. Nghiệm pháp ngăn kéo trước dương tính chứng tỏ dây này đã đứt hoàn toàn.", en: "The WEAKEST ligament and the FIRST torn in an ankle sprain — it is tightest in plantarflexion with inversion, exactly the position of injury. Point tenderness just anterior and inferior to the lateral malleolus is the classic sign, and a positive anterior drawer test indicates complete rupture.", zh: "最薄弱、扭伤时最先撕裂的韧带——在跖屈内翻位最紧张，恰为受伤时的姿势。外踝前下方局限性压痛为典型体征，前抽屉试验阳性提示完全断裂。" } },
      { key: "calcaneofibular", meshName: "Calcaneofibular ligament.r", offset: [0, 0], label: { vi: "Dây chằng gót – mác", en: "Calcaneofibular ligament", zh: "跟腓韧带" }, latinName: "Ligamentum calcaneofibulare",
        note: { vi: "Dây thứ hai bị rách khi lực lật vào trong đủ mạnh. Nó bắc qua CẢ HAI khớp — khớp cổ chân và khớp dưới sên — nên đứt dây này làm mất vững theo cả hai hướng và cổ chân “trượt” khi đi trên nền không phẳng. Nghiệm pháp nghiêng xương sên dùng để đánh giá riêng dây này. Rách cả hai dây trước và dưới là bong gân độ III cần bất động.", en: "The second ligament to tear when inversion force continues. It spans BOTH the ankle and subtalar joints, so its rupture destabilises the hindfoot in two planes and the ankle 'gives way' on uneven ground. The talar tilt test assesses it specifically; rupture of both this and the anterior talofibular ligament is a grade III sprain requiring immobilisation.", zh: "内翻暴力持续时第二个撕裂的韧带。它跨越踝与距下两个关节，故断裂使后足在两个平面上失稳，行走于不平地面时踝“打软”。距骨倾斜试验专用于评估此韧带；与距腓前韧带同时断裂即III度扭伤，需制动。" } },
      { key: "calcaneal-tendon", meshName: "Calcaneal tendon.r", offset: [0, 0], label: { vi: "Gân gót (gân Achilles)", en: "Calcaneal tendon", zh: "跟腱" }, latinName: "Tendo calcaneus",
        note: { vi: "Gân KHOẺ NHẤT và DÀY NHẤT cơ thể, chịu lực tới nhiều lần trọng lượng cơ thể khi chạy nhảy. Vùng cách chỗ bám 2–6 cm là nơi cấp máu kém nhất nên cũng là nơi hay đứt nhất, thường ở người trung niên chơi thể thao ngắt quãng. Đứt gân cho dấu hiệu bóp bắp chân không làm gấp gan chân, và người bệnh vẫn đi được nhờ các cơ gấp khác nên dễ bị bỏ sót.", en: "The STRONGEST and THICKEST tendon in the body, loaded to several times body weight when running. The zone 2–6 cm above its insertion is least vascularised and therefore the usual site of rupture, typically in middle-aged intermittent athletes. Rupture abolishes plantarflexion on calf squeeze, yet the patient can still walk using other flexors — which is why it is so often missed.", zh: "全身最强最厚的肌腱，奔跑时承受数倍体重的负荷。止点上方2–6厘米处血供最差，也是最常断裂处，多见于间歇运动的中年人。断裂时挤压小腿不引起跖屈，但患者借助其他屈肌仍能行走，故极易漏诊。" } },
      { key: "flexor-retinaculum-ankle", meshName: "Flexor retinaculum of ankle.r", offset: [0, 0], label: { vi: "Mạc giữ gân gấp (trần ống cổ chân)", en: "Flexor retinaculum of the ankle", zh: "屈肌支持带" }, latinName: "Retinaculum musculorum flexorum",
        note: { vi: "Bắc từ mắt cá trong xuống xương gót, biến rãnh sau mắt cá trong thành ỐNG CỔ CHÂN. Trong ống, thứ tự từ trước ra sau là: gân chày sau, gân gấp các ngón dài, động mạch và tĩnh mạch chày sau, thần kinh chày, rồi gân gấp ngón cái dài. Chèn ép trong ống gây hội chứng ống cổ chân — đau rát gan bàn chân tăng về đêm, tương tự ống cổ tay nhưng ở chân.", en: "Runs from the medial malleolus to the calcaneus, converting the groove behind the malleolus into the TARSAL TUNNEL. From front to back it contains tibialis posterior tendon, flexor digitorum longus, posterior tibial vessels, tibial nerve, then flexor hallucis longus. Compression here causes tarsal tunnel syndrome — burning sole pain worse at night, the foot's equivalent of carpal tunnel syndrome.", zh: "自内踝连至跟骨，将内踝后方的沟围成跗管。管内由前向后依次为胫骨后肌腱、趾长屈肌腱、胫后血管、胫神经、拇长屈肌腱。此处受压即跗管综合征——足底灼痛、夜间加重，为足部的“腕管综合征”。" } },
      { key: "inferior-extensor-retinaculum", meshName: "Inferior extensor retinaculum of ankle.r", offset: [0, 0], label: { vi: "Mạc giữ gân duỗi dưới", en: "Inferior extensor retinaculum", zh: "伸肌下支持带" }, latinName: "Retinaculum musculorum extensorum inferius",
        note: { vi: "Dải sợi hình chữ Y ở mu cổ chân, giữ các gân duỗi áp sát xương khi gấp mu chân — không có nó thì gân bật lên như dây cung mỗi lần nhấc bàn chân. Nó cũng tạo thành các bao riêng cho từng gân. Vì nằm nông ngay dưới da, dải này dễ bị dày lên do cọ sát với dây giày và gây đau mu cổ chân ở người chạy bộ.", en: "A Y-shaped band on the dorsum holding the extensor tendons against bone during dorsiflexion — without it they would bowstring each time the foot lifts. It also forms separate compartments for individual tendons. Lying just under the skin, it thickens with friction from shoe laces and causes dorsal ankle pain in runners.", zh: "足背的Y形纤维带，背伸时将伸肌腱固定于骨面——若无此带，每次抬足肌腱即弓弦样弹起。它还为各肌腱形成独立分隔。因位置浅表，易因鞋带摩擦而增厚，导致跑步者足背疼痛。" } },
      { key: "long-plantar", meshName: "Long plantar ligament.r", offset: [0, 0], label: { vi: "Dây chằng gan chân dài", en: "Long plantar ligament", zh: "足底长韧带" }, latinName: "Ligamentum plantare longum",
        note: { vi: "Dây chằng DÀI NHẤT của bàn chân, đi từ mặt dưới xương gót ra trước tới các nền xương bàn chân. Cùng dây chằng gan chân ngắn và cân gan chân, nó là bộ ba GIỮ VÒM DỌC bàn chân — vòm này chịu lực bằng cơ chế dây cung chứ không phải bằng cơ, nên vẫn đứng vững được cả khi các cơ nội tại mỏi. Suy yếu bộ ba này dẫn tới bàn chân bẹt mắc phải ở người lớn.", en: "The LONGEST ligament of the foot, running from the plantar surface of the calcaneus forward to the metatarsal bases. With the short plantar ligament and the plantar aponeurosis it forms the trio that MAINTAINS THE LONGITUDINAL ARCH — a tie-beam mechanism rather than a muscular one, which is why the arch holds even when the intrinsic muscles fatigue. Failure of this trio produces adult acquired flatfoot.", zh: "足部最长的韧带，自跟骨跖面前行至跖骨底。与足底短韧带、足底腱膜共同构成维持足纵弓的三联结构——以系梁机制而非肌力承载，故内在肌疲劳时足弓仍能维持。此三联失效即成人获得性扁平足。" } },
      { key: "tibia-ankle", meshName: "Tibia.r", offset: [0, 0], label: { vi: "Xương chày (mắt cá trong)", en: "Tibia — medial malleolus", zh: "胫骨（内踝）" }, latinName: "Malleolus medialis",
        note: { vi: "Đầu dưới xương chày tạo trần và thành trong của gọng kìm. Mắt cá trong ngắn hơn mắt cá ngoài và nằm ra TRƯỚC hơn — sự bất đối xứng đó là lý do bàn chân lật vào trong dễ hơn lật ra ngoài. Gãy cả hai mắt cá kèm rách dây chằng chày mác dưới làm gọng kìm toác ra, xương sên trượt, và bắt buộc phải mổ cố định để phục hồi khe khớp.", en: "The distal tibia forms the roof and medial wall of the mortise. The medial malleolus is shorter than the lateral and lies more ANTERIORLY — an asymmetry that is why the foot inverts more readily than it everts. Fracture of both malleoli with rupture of the inferior tibiofibular ligaments widens the mortise and lets the talus shift, mandating surgical fixation.", zh: "胫骨下端构成榫眼的顶与内侧壁。内踝较外踝短且位置偏前——此不对称正是足内翻较外翻更易发生的原因。双踝骨折合并下胫腓韧带断裂使榫眼增宽、距骨移位，必须手术固定以恢复关节间隙。" } },
      { key: "fibula-ankle", meshName: "Fibula.r", offset: [0, 0], label: { vi: "Xương mác (mắt cá ngoài)", en: "Fibula — lateral malleolus", zh: "腓骨（外踝）" }, latinName: "Malleolus lateralis",
        note: { vi: "Mắt cá ngoài xuống THẤP HƠN mắt cá trong khoảng 1 cm và nằm ra sau hơn, tạo thành thành ngoài của gọng kìm và cản trở bàn chân lật ra ngoài. Xương mác gần như không chịu trọng lực — chỉ khoảng một phần mười — nên có thể lấy một đoạn thân xương mác làm mảnh ghép xương ở nơi khác mà không ảnh hưởng đi lại, miễn là giữ nguyên đoạn mắt cá.", en: "The lateral malleolus descends about 1 cm LOWER than the medial and lies more posteriorly, forming the lateral wall of the mortise and resisting eversion. The fibula bears almost no weight — about a tenth — so a length of its shaft can be harvested as a bone graft without affecting walking, provided the malleolar segment is preserved.", zh: "外踝较内踝低约1厘米且位置偏后，构成榫眼外侧壁并阻止外翻。腓骨几乎不承重——约十分之一——故可取其骨干作骨移植而不影响行走，前提是保留踝部节段。" } },
    ],
  },
});

